(() => {
    try {
      const arr = Array.isArray(order.items) ? order.items : JSON.parse(order.items as string);
      return arr as { name: string; quantity: number }[];
    } catch {
      return [];
    }
  })

(() => {
    if (order.channel === "outside") return order.address_line ?? null;
    const parts = [
      order.place_name,
      (order as unknown as Record<string, string | null>).floor
        ? `${t("order.location.floorAbbrev", "Fl.")} ${(order as unknown as Record<string, string | null>).floor}`
        : null,
      (order as unknown as Record<string, string | null>).unit_number,
    ].filter(Boolean);
    return parts.length ? parts.join(" · ") : null;
  })

(() => {
    if (!branchId) return "branch";
    // Browse-only jumps straight to the menu — no channel/phone/location gates.
    if (browseOnly) return "menu";
    if (!selectedChannel) return "channel";
    if (!resolvedPhone) return "phone";
    if (needsLocation && !locationDone) return "location";
    if (enteredCheckout) return "checkout";
    return "menu";
  })
